const FALLBACK_SUPABASE_URL = "https://placeholder.invalid";
const FALLBACK_SUPABASE_PUBLISHABLE_KEY = "development-placeholder-key";

function readEnv(name: string): string {
  const value = import.meta.env[name];
  return typeof value === "string" ? value.trim() : "";
}

export function getRuntimeConfig() {
  const supabaseUrl = readEnv("VITE_SUPABASE_URL");
  const supabasePublishableKey =
    readEnv("VITE_SUPABASE_PUBLISHABLE_KEY") || readEnv("VITE_SUPABASE_ANON_KEY");
  const missingSupabaseConfig = !supabaseUrl || !supabasePublishableKey;

  return {
    supabaseUrl: supabaseUrl || FALLBACK_SUPABASE_URL,
    supabasePublishableKey: supabasePublishableKey || FALLBACK_SUPABASE_PUBLISHABLE_KEY,
    missingSupabaseConfig,
  };
}
